<?php
$admin_title='Manage Services';require __DIR__.'/layout_top.php';$pdo=db();$edit=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='delete'){$pdo->prepare('DELETE FROM services WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Service deleted.');redirect('admin/services.php');}$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$order=(int)($_POST['display_order']??0);$status=$_POST['status']==='inactive'?'inactive':'active';if(strlen($name)<2||strlen($description)<4)throw new RuntimeException('Complete the service name and description.');$image=upload_image('image','services');if($action==='update'){$id=(int)$_POST['id'];$sql='UPDATE services SET name=?,description=?,display_order=?,status=?'.($image?',image_path=?':'').' WHERE id=?';$params=[$name,$description,$order,$status];if($image)$params[]=$image;$params[]=$id;$pdo->prepare($sql)->execute($params);flash('success','Service updated.');}else{$pdo->prepare('INSERT INTO services(name,description,image_path,display_order,status) VALUES(?,?,?,?,?)')->execute([$name,$description,$image,$order,$status]);flash('success','Service added.');}redirect('admin/services.php');}catch(Throwable $e){flash('error',$e->getMessage());redirect('admin/services.php');}}
if(isset($_GET['edit'])){$stmt=$pdo->prepare('SELECT * FROM services WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch()?:null;}$services=$pdo->query('SELECT * FROM services ORDER BY display_order,id')->fetchAll();
?>
<span class="eyebrow" style="color:#ae7d2c">Shop services</span><h1><?= $edit?'Edit service':'Manage services' ?></h1><div class="grid two" style="grid-template-columns:360px 1fr"><form class="form-card" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="form-grid" style="grid-template-columns:1fr"><label>Service name<input required name="name" value="<?=e($edit['name']??'')?>"></label><label>Description<textarea required name="description"><?=e($edit['description']??'')?></textarea></label><label>Image (optional)<input type="file" accept=".jpg,.jpeg,.png,.webp" name="image"></label><label>Display order<input type="number" name="display_order" value="<?=e((string)($edit['display_order']??0))?>"></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label><button class="button dark"><?=$edit?'Save service':'Add service'?></button></div></form><div class="table-wrap"><table><thead><tr><th>Service</th><th>Description</th><th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><?=e($s['name'])?></td><td><?=e($s['description'])?></td><td><?=$s['display_order']?></td><td><?=e($s['status'])?></td><td><div class="actions"><a class="button small outline" href="?edit=<?=$s['id']?>">Edit</a><form method="post" data-confirm="delete"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="button small danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require __DIR__.'/layout_bottom.php'; ?>
